{
  "summary": "Fix the restore flow by setting phase to 'restoring' initially, populating threadIds, then setting phase to 'running' only after restoration completes. Also preserve existing threadIds from the snapshot instead of overwriting them.",
  "files": [
    {
      "path": "apps/game-runtime/src/runtime/restore.ts",
      "content": "import type { RuntimeState } from "./types";
import { ThreadBootstrapper } from "./bootstrap";

export type Snapshot = {
  agentIds: string[];
  threadIds: Record<string, string>;
};

export function restoreRuntime(
  snapshot: Snapshot,
  state: RuntimeState,
  bootstrapper: ThreadBootstrapper,
): RuntimeState {
  state.phase = "restoring";
  state.threadIds = { ...snapshot.threadIds };
  for (const agentId of snapshot.agentIds) {
    if (!(agentId in state.threadIds)) {
      state.threadIds[agentId] = bootstrapper.ensureThread(agentId);
    }
  }
  state.phase = "running";
  return state;
}
